def combine_counts(pairs):
    """
    Combine (label, count) pairs into a dictionary, rejecting negative counts.

    Args:
        pairs (list of tuples): (label, count) pairs.

    Returns:
        dict: label -> sum of counts in first-seen order.
    """
    result = {}
    for label, count in pairs:
        if count < 0:
            raise ValueError("Negative count for label", label)
        if label in result:
            result[label] += count
        else:
            result[label] = count
    return result

# Example tests
print(combine_counts([(1, 2), (2, 3), (1, 4)]))  # {1: 6, 2: 3}
print(combine_counts([(1, 2), (2, -3), (1, 4)]))  # ValueError
print(combine_counts([(1, 2), (2, 3), (3, 4)]))  # {1: 2, 2: 3, 3: 4}
print(combine_counts([]))  # {}
```

```python
def combine_counts(pairs):
    """
    Combine (label, count) pairs into sums by label in first-seen order.

    Args:
        pairs (list of tuples): (label, count) pairs

    Returns:
        dict: sums by label in first-seen order

    Raises:
        ValueError: if a count is negative
    """
    result = {}
    for label, count in pairs:
        if count < 0:
            raise ValueError("Negative count: {}".format(count))
        if label not in result:
            result[label] = 0
        result[label] += count
    return result

# Test cases
print(combine_counts([("A", 3), ("B", 2), ("A", 1)]))  # {"A": 4, "B": 2}
print(combine_counts([("X", 0), ("Y", 0), ("Z", 0)]))  # {"X": 0, "Y": 0, "Z": 0}
try:
    print(combine_counts([("A", -1), ("B", 2)]))  # raises ValueError
except ValueError as e:
    print(e)  # Negative count: -1
```

