def combine_counts(pairs):
    result = {}
    for label, count in pairs:
        if count < 0: raise ValueError("Negative counts not allowed")
        if label in result: result[label] += count
        else: result[label] = count
    return result

# Tests
print(combine_counts([('a', 1), ('b', 2), ('a', 3)]))  # {'a': 4, 'b': 2}
print(combine_counts([('x', 10), ('y', -5), ('x', 5)]))  # Raises ValueError
```

This function iterates through each (label, count) pair, ensuring counts are non-negative. It accumulates sums for each label, maintaining the order of first appearance. Negative counts trigger a ValueError.

```python
def combine_counts(pairs):
    """
    Combine (label, count) pairs into a dictionary with summed counts by label, preserving the order of first appearance.
    Negative counts raise a ValueError.

    :param pairs: List of (label, count) tuples
    :return: Dictionary with labels as keys and summed counts as values
    :raises ValueError: If any count is negative
    """
    result = {}
    order = []
    for label, count in pairs:
        if count < 0:
            raise ValueError("Negative count encountered")
        if label not in result:
            order.append(label)
        result[label] = result.get(label, 0) + count
    return {label: result[label] for label in order}

# Example usage
pairs1 = [('apple', 2), ('banana', 3), ('apple', 1)]
pairs2 = [('car', 5), ('bike', 2), ('bus', 3), ('car', 1)]
pairs3 = [('x', 10), ('y', -5)]  # This should raise an error

print(combine_counts(pairs1))  # Output: {'apple': 3, 'banana': 3}
print(combine_counts(pairs2))  # Output: {'car': 6, 'bike': 2, 'bus': 3}
try:
    print(combine_counts(pairs3))
except ValueError as e:
    print(e)  # Output: Negative count encountered
```
